comment_data.body:
ai suggestion :

```c
  /// Parse 'previewpopup' ("height:N,width:N,border:style") into `config`.
  ///
  /// @param value  the option value to parse (e.g. `p_pvp`).
  ///
  /// @return false on an invalid value; caller emits E474.                                                                                                                                                                               
  bool win_float_parse_option(char *value, WinConfig *config)
    FUNC_ATTR_NONNULL_ALL
  {
    int height = 0;
    int width = 0;
    bool has_border = false;

    char item[64];  // one "key:value" part; longest is "border:rounded"
    for (char *p = value; *p != NUL;) {
      copy_option_part(&p, item, sizeof(item), ",");

      char *val = vim_strchr(item, ':');
      if (val == NULL) {
        return false;  // every item must be "key:value"
      }
      *val++ = NUL;

      if (strcmp(item, "border") == 0) {
        // A custom (comma-separated) border can't be given here; only named
        // styles survive the comma split above. See 'previewpopup'.
        Error err = ERROR_INIT;
        bool ok = *val != NUL && parse_winborder(config, val, &err);
        api_clear_error(&err);
        if (!ok) {
          return false;
        }
        has_border = true;
      } else if (strcmp(item, "height") == 0 || strcmp(item, "width") == 0) {
        char *end = val;
        int n = getdigits_int(&end, false, 0);
        if (end == val || *end != NUL || n < 1) {
          return false;
        }
        *(item[0] == 'h' ? &height : &width) = n;
      } else {
        return false;  // unknown key
      }
    }

    config->height = height;
    config->width = width;

    // Without "border:" inherits 'winborder'.
    if (!has_border) {
      config->border = false;
      if (*p_winborder != NUL) {
        Error err = ERROR_INIT;
        parse_winborder(config, p_winborder, &err);
        api_clear_error(&err);
      }
    }

    if (!config->border) {
      config->title = false;
    }

    return true;
  }
```

then, call sites become explicit about what they parse:

```c
  // optionstr.c — did_set_previewpopup validates the just-set value
  WinConfig fconfig = WIN_CONFIG_INIT;
  if (!win_float_parse_option(p_pvp, &fconfig)) {
    return e_invarg;
  }

  // winfloat.c — win_float_create_preview builds the real config
  if (preview && !win_float_parse_option(p_pvp, &config)) {
    emsg(_(e_invarg));
    return NULL;
  }
